def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    out = [row[:] for row in grid]

    # Find vertical boundary runs: columns containing non-background cells
    # in consecutive rows.
    rail_rows = {}
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != bg]
        if cols:
            rail_rows[r] = cols

    runs = []
    for r in sorted(rail_rows):
        if not runs or r != runs[-1][-1] + 1:
            runs.append([r])
        else:
            runs[-1].append(r)

    if len(runs) < 2:
        return out

    # In each run, its single-color edge cell is the rail; other non-bg
    # cells on the row are markers.
    markers_by_run = []
    for run in runs:
        markers = []
        for r in run:
            cells = [(c, grid[r][c]) for c in range(w)
                     if grid[r][c] != bg]
            rail_candidates = [(c, v) for c, v in cells if v in (8, 9)]
            rail = rail_candidates[0][0] if rail_candidates else (
                0 if cells[0][0] < w // 2 else w - 1)
            for c, color in cells:
                if c != rail and color not in (8, 9):
                    markers.append((r, c, color, rail))
        markers_by_run.append(markers)

    for idx, run in enumerate(runs):
        markers = markers_by_run[idx]
        if not markers:
            continue
        start = run[0]
        # Project markers in their own panel to its boundary.
        for r, c, color, rail in markers:
            step = 1 if rail > c else -1
            for j in range(c, rail, step):
                out[r][j] = color
            out[r][c] = 4

        # Reflect the marker row offsets into the next boundary panel,
        # filling from its opposite edge up to (but not over) its rail.
        other_idx = (idx + 1) % len(runs)
        other = runs[other_idx]
        other_start = other[0]
        for r, c, color, rail in markers:
            rr = other_start + (r - start)
            if rr not in other:
                continue
            other_rail = next((j for j in range(w)
                               if grid[rr][j] in (8, 9)), None)
            if other_rail is None:
                continue
            for j in range(w):
                if j != other_rail:
                    out[rr][j] = color
    return out
